import{_ as l,l as o,o as a,c as s,v as n,p as i,x as t,d as p,i as M,S as c}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Qwen2.5-1M 长上下文","description":"","frontmatter":{"title":"Qwen2.5-1M 长上下文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen25-1m.md","filePath":"llm/qwen25-1m.md","lastUpdated":1789023840000}'),d={name:"llm/qwen25-1m.md"};function h(E,e,A,B,m,u){const r=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="qwen2-5-1m-长上下文" tabindex="-1">Qwen2.5-1M 长上下文 <a class="header-anchor" href="#qwen2-5-1m-长上下文" aria-label="Permalink to &quot;Qwen2.5-1M 长上下文&quot;">​</a></h1><div class="epigraph"><p>预训练只训到 256K，推理用块注意力与稀疏核把可用窗口拉到 1M；短样本上的对齐也能泛到长对话。</p><footer>—— Yang 等，Qwen2.5-1M Technical Report，arXiv:2501.15383</footer></div><p>Qwen2.5-1M 是通义把 Qwen2.5 窗口做到 <strong>100 万 token</strong> 的专线：开源 <strong>7B-Instruct-1M</strong> 与 <strong>14B-Instruct-1M</strong>（Apache 2.0），云上另有 MoE <strong>Qwen2.5-Turbo</strong>。常规 Qwen2.5 Instruct 默认是 32K 预训练加外推到 128K，与 1M 检查点不是同一张权重。报告的原文贡献分两块：<strong>怎么把训练长度渐进加到 256K 而不把短任务打崩</strong>，以及 <strong>开源推理框架如何用训练免费外推 + 稀疏注意力把 1M prefill 加速 3–7 倍</strong>。<a href="/llm/dual-chunk-attention">Dual Chunk Attention</a> 与 <a href="/llm/yarn">YaRN</a> 有专文，这里只写 1M 报告如何把它们接进训练表与部署。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>仓库级代码、多文档研究、超长日志，128K 仍然不够。直接在 1M 上做满注意力预训练，激活与 KV 的账单不可接受；只做推理外推、权重仍停在 32K，复杂检索（多针、多值）会先于简单 passkey 崩掉。自然长文本往往局部连贯、远距关联弱：模型可以靠近邻预测下一个词，学不会「第 3 章的定义约束第 18 章的用法」。</p><p>后训练更缺标注：人读百万字再写答案既贵又不稳。若长指令 SFT 冲掉短任务，产品无法用同一权重既聊短又读长。服务侧 1M 的注意力可占前向 90% 以上时间，满注意力 + 整段 prefill 会在激活显存上先 OOM（报告举例：7B 单层 MLP 在 1M 上激活约 71GB）。</p><h3 id="训练长度不是服务长度" tabindex="-1">训练长度不是服务长度 <a class="header-anchor" href="#训练长度不是服务长度" aria-label="Permalink to &quot;训练长度不是服务长度&quot;">​</a></h3><p>1M 系列架构与 Qwen2.5 同构：GQA、SwiGLU、RoPE、QKV bias、RMSNorm。7B 为 28 层、28/4 头；14B 为 48 层、40/8 头；生成长度仍标 8K。训练最长 <strong>262144</strong>，1M 是推理外推目标。把 <code>max_position_embeddings=1000000</code> 写进配置，不等于权重见过 1M 的相对位置。</p><p><span class="marginnote">Passkey 在 1M 上好看，只说明还能找一个隐藏数。报告用 RULER 的多查询 / 多值 NIAH 对照：DCA 对所有 Instruct 都有帮助，但 256K 训练过的 1M 权重外推明显稳于 128K 版硬拉到 1M。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练从 Qwen2.5 Base 的中间检查点接着做长窗。自然语言长文本来自 Common Crawl、arXiv、书籍、代码仓。合成任务专门造远距依赖：FIM 在不同位置挖空洞；按关键词或按位置取段落；打乱段落再恢复顺序。这些任务迫使预测依赖远键，而不是只抄局部。</p><p>长度五段。前两段与常规 2.5 相同：4K，再 32K 并把 RoPE 基数从 1 万调到 100 万（ABF）。随后 65,536 / 131,072 / 262,144，基数分别为 100 万、500 万、1000 万。每一档 75% 当前最大长度、25% 更短，避免忘掉短序列。14B 在 RULER 上：32K 训完后 128K 任务只有 37.6；训到 256K 后 128K 升到 87.6——更长的训练长度会抬高相对短的长窗任务。</p><h3 id="两段-sft-短样本-rl" tabindex="-1">两段 SFT，短样本 RL <a class="header-anchor" href="#两段-sft-短样本-rl" aria-label="Permalink to &quot;两段 SFT，短样本 RL&quot;">​</a></h3><p>长指令用智能体合成：从预训练文档抽一段让 Qwen2.5 出题（摘要、检索、多跳 QA、推理、代码等），再用 Qwen-Agent 在<strong>全文</strong>上检索、分段读、逐步推理写出答案。人标长文不可规模化时，这是报告的替代。</p><p>SFT 两阶段。第一阶段与常规 2.5 一样，只用 ≤32K 短指令、步数相同，保住短任务。第二阶段混入最长到 256K 的长短数据，配比避免遗忘。RL 用离线偏好优化（类 DPO），<strong>样本全是 ≤8K 的短对</strong>——与其他 Qwen2.5 的离线 RL 对相同。Longbench-Chat 上，短 RL 之后 7B-1M 从 7.32 到 8.08，Turbo 从 7.60 到 8.34，说明短偏好可以泛到长对话。</p><p>推理框架三件套。长度外推：DCA 把相对位置重映射到训练长度内（块内 / 块间 / 相邻块），再叠 YaRN 的注意力温度 \\(1/\\sqrt{t}=0.1\\ln s+1\\)（\\(s\\) 为推理长与训练长之比）。稀疏注意力基于 MInference 的 Vertical-Slash：离线搜每头要保留的竖线与斜线数，在线用 last_q 对全部键打分再只算关键键。再加 <strong>chunked prefill</strong>（块长 32768）把激活显存砍约 96.7%，并与 DCA 拼在一起；另做稀疏配置精修以挽回长序列精度。引擎层还有核、流水并行与调度。开源集成进 vLLM。</p>',16)),(a(),i(c,null,{default:t(()=>[M(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22Qwen2.5%20%E4%B8%AD%E9%97%B4%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20P%5B%22%E6%B8%90%E8%BF%9B%204K%E2%86%9232K%E2%86%9264K%E2%86%92128K%E2%86%92256K%22%5D%0A%20%20SYN%5B%22FIM%20%2F%20%E6%A3%80%E7%B4%A2%20%2F%20%E6%AE%B5%E8%90%BD%E9%87%8D%E6%8E%92%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20S1%5B%22SFT%20%E4%BB%85%E7%9F%AD%E6%8C%87%E4%BB%A4%20%E2%89%A432K%22%5D%0A%20%20AGENT%5B%22Agent%20%E5%90%88%E6%88%90%E9%95%BF%20QA%22%5D%20--%3E%20S2%5B%22SFT%20%E9%95%BF%E7%9F%AD%E6%B7%B7%E5%90%88%20%E2%89%A4256K%22%5D%0A%20%20S1%20--%3E%20S2%0A%20%20S2%20--%3E%20RL%5B%22%E7%9F%AD%E6%A0%B7%E6%9C%AC%E7%A6%BB%E7%BA%BF%20RL%20%E2%89%A48K%22%5D%0A%20%20RL%20--%3E%20INF%5B%22DCA%20%2B%20YaRN%20%2B%20MInference%20%E5%88%86%E5%9D%97%20prefill%22%5D%0A%20%20INF%20--%3E%20M%5B%22%E6%9C%8D%E5%8A%A1%201M%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合成远距任务改变的是<strong>哪些键对损失有贡献</strong>：段落重排的监督信号跨段，FIM 的空洞两侧都要读。渐进加长则让 RoPE 相位逐步进入新区间，避免一次把基数跳到 \\(10^7\\) 时短窗任务崩溃。75/25 的长短混合是同一权重上的多任务，不是两个模型。</p><h3 id="_1m-是折叠后的相对位置" tabindex="-1">1M 是折叠后的相对位置 <a class="header-anchor" href="#_1m-是折叠后的相对位置" aria-label="Permalink to &quot;1M 是折叠后的相对位置&quot;">​</a></h3><p>短 RL 能泛到长上下文，说明「是否按人类偏好组织回答」对长度不敏感；真正长度敏感的是检索与多跳，那部分靠预训练与第二段 SFT。DCA 保证任意两 token 的相对位置仍落在 256K 训练支撑里，因此 1M 不是「看见过 1M 的 \\(\\Delta\\)」，而是「把 1M 的 \\(\\Delta\\) 折叠回见过的集合」。稀疏核假设长序列注意力呈竖线+斜线；若某头的模式不是这样，近似会丢针。分块 prefill 改变的是激活峰值，不是数学上的注意力集合——但与 MInference 结合时，关键 token 的选择必须在块之间对齐，否则竖线会被切碎。参见已有的 <a href="/llm/chunked-prefill">chunked prefill</a> 专文：1M 报告把它与稀疏核绑在同一套服务路径上。</p><p><span class="marginnote">YaRN 温度与 DCA 一起用时，短序列行为应保持不变，这是报告明确写出的产品约束：1M 权重在短任务上不能明显弱于 128K 版。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开源只有 7B/14B Instruct-1M，没有 72B-1M 权重；Turbo 是 API MoE，不可当开源稠密的隐藏档。生成长度 8K，1M 是输入侧。部署必须走匹配的 vLLM / 官方框架：无 DCA 时 1M 相对位置 OOD；无分块 prefill 时激活先爆；无稀疏时 1M 注意力时间不可用。MInference 的离线头配置换模型要重搜。量化 KV 在早期集成里受限，规划显存不能抄常规 128K 的量化表。</p><p>评测上 14B-1M 报告称长任务显著好于 GPT-4o-mini 且窗口长八倍；短任务以「不明显回退」为成功标准，不是短榜新 SOTA。不要把 1M 针测满分写成「已理解整本法律汇编」。</p><p><span class="marginnote">应用侧仍要切文档：1M 是上限不是默认。无结构的网页垃圾填满窗口，稀疏注意力会去拟合竖线噪声。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen2.5-1M 在同构 Qwen2.5 上渐进预训练到 256K，开源 7B/14B Instruct-1M，推理外推到 1M。</li><li>数据侧用 FIM、检索与段落重排加强远距依赖；后训练先短 SFT 再长短混合，短样本 RL 泛到长对话。</li><li>服务侧 DCA+YaRN 外推，MInference+分块 prefill 把 1M prefill 加速约 3–7 倍。</li><li>常规 128K Instruct 与 1M 权重不可互换。</li><li>出处：Yang 等，<em>Qwen2.5-1M Technical Report</em>，arXiv:2501.15383，2025。DCA 原论文 An 等，arXiv:2402.17463。</li></ul>',11))])}const g=l(d,[["render",h]]);export{_ as __pageData,g as default};
